('탈영일지','아포리아',array['드라마']::text[],'1984년 군생활을 이어가던 ‘최금혁’은 선임들의 모진 갈굼과','naver','https://comic.naver.com/webtoon/list?titleId=773523','https://shared-comic.pstatic.net/thumb/webtoon/773523/thumbnail/thumbnail_IMAG21_4048844244048492131.jpg'),
('보살님이 캐리해!','성코·콩자',array['액션']::text[],'억겁의 시간을 넘어 환생한 보살들이여','naver','https://comic.naver.com/webtoon/list?titleId=756790','https://shared-comic.pstatic.net/thumb/webtoon/756790/thumbnail/thumbnail_IMAG21_3703701840389748281.jpg'),
('오파츠','성진·부겸',array['판타지']::text[],'이 세상에 존재할 수 없는 물건인 ‘오파츠’를 소유한 이들.','naver','https://comic.naver.com/webtoon/list?titleId=744381','https://shared-comic.pstatic.net/thumb/webtoon/744381/thumbnail/thumbnail_IMAG21_3618754671452368996.jpg'),
('평행우주','현용민',array['코미디']::text[],'체구도 작고 공부도 못 하는 17살의 ''이우주''는 어느 날, 자신을 괴롭히는 ‘표영배’ 녀석들에게 쫓겨 학교 뒷산 낭떠러지에서 떨어진다.','naver','https://comic.naver.com/webtoon/list?titleId=789987','https://shared-comic.pstatic.net/thumb/webtoon/789987/thumbnail/thumbnail_IMAG21_3762249760002093369.jpg')
),
ins as (
  insert into public.works (title_ko, author, genres, blurb_ko, cover_url, status, is_curated, sort)
  select i.title, i.author, i.genres, i.blurb, nullif(i.cover,''), '완결', false,
         3500 + row_number() over (order by i.title)
    from imp i
   where not exists (select 1 from public.works w where w.title_ko = i.title)
  returning id, title_ko
)
insert into public.work_legal_links (work_id, platform_key, url, sort)
select ins.id, imp.pk, imp.url, 0
  from imp join ins on ins.title_ko = imp.title;


